command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ((git rev-parse origin/main).Trim() -ne "92c16faf6c56c89cf4bff5230482db3ac312a82f") { throw "main moved" }
python -X utf8 -c "import ctypes; from ctypes import wintypes as w; u=ctypes.WinDLL('user32',use_last_error=True); H=type('H',(ctypes.Structure,),{'_fields_':[('cbSize',w.UINT),('dwFlags',w.DWORD),('lpszDefaultScheme',w.LPWSTR)]}); x=H(); x.cbSize=ctypes.sizeof(x); ok=u.SystemParametersInfoW(0x0042,x.cbSize,ctypes.byref(x),0); print('HIGH_CONTRAST_QUERY_OK='+str(bool(ok))); print('HIGH_CONTRAST_ON='+str(bool(x.dwFlags&1))); print('HIGH_CONTRAST_SCHEME='+repr(x.lpszDefaultScheme))"
if ($LASTEXITCODE -ne 0) { throw "high contrast state query failed" }
Write-Host "HIGH_CONTRAST_READONLY_PROBE_PASS"
